CREATE EXTENSION IF NOT EXISTS unaccent;
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE TABLE customers (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, full_name varchar(120) NOT NULL, email varchar(254) UNIQUE NOT NULL, password_hash varchar(100) NOT NULL, phone varchar(20), shipping_address varchar(500), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE categories (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(100) NOT NULL UNIQUE, description text, active boolean NOT NULL DEFAULT true);
CREATE TABLE products (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, category_id bigint NOT NULL REFERENCES categories, name varchar(200) NOT NULL, description text NOT NULL, active boolean NOT NULL DEFAULT true, embedding jsonb, search_text text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE product_variants (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id bigint NOT NULL REFERENCES products, sku varchar(80) UNIQUE NOT NULL, size varchar(20) NOT NULL, color varchar(50) NOT NULL, price numeric(18,2) NOT NULL CHECK(price>=0), stock_quantity integer NOT NULL CHECK(stock_quantity>=0), active boolean NOT NULL DEFAULT true, UNIQUE(product_id,size,color));
CREATE INDEX variant_filter_idx ON product_variants(product_id,active,size,color,price);
CREATE TABLE product_images (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id bigint NOT NULL REFERENCES products, image_url varchar(1000) NOT NULL, alt_text varchar(200) NOT NULL, display_order integer NOT NULL CHECK(display_order>=0), UNIQUE(product_id,display_order));
CREATE TABLE carts (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, customer_id bigint UNIQUE NOT NULL REFERENCES customers, version bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cart_items (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, cart_id bigint NOT NULL REFERENCES carts ON DELETE CASCADE, variant_id bigint NOT NULL REFERENCES product_variants, quantity integer NOT NULL CHECK(quantity>0), added_at timestamptz NOT NULL DEFAULT now(), UNIQUE(cart_id,variant_id));
CREATE TABLE orders (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, customer_id bigint NOT NULL REFERENCES customers, order_number varchar(80) UNIQUE NOT NULL, status varchar(20) NOT NULL CHECK(status IN ('PENDING','CONFIRMED','SHIPPING','COMPLETED','CANCELLED')), receiver_name varchar(120) NOT NULL, receiver_phone varchar(10) NOT NULL, shipping_address varchar(500) NOT NULL, total_amount numeric(18,2) NOT NULL CHECK(total_amount>=0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE order_items (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id bigint NOT NULL REFERENCES orders, variant_id bigint NOT NULL REFERENCES product_variants, product_name varchar(200) NOT NULL, sku varchar(80) NOT NULL, size varchar(20) NOT NULL, color varchar(50) NOT NULL, unit_price numeric(18,2) NOT NULL CHECK(unit_price>=0), quantity integer NOT NULL CHECK(quantity>0));
CREATE TABLE payments (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id bigint UNIQUE NOT NULL REFERENCES orders, method varchar(20) NOT NULL CHECK(method IN ('COD','BANK_TRANSFER')), status varchar(20) NOT NULL CHECK(status IN ('PENDING','PAID','FAILED','REFUNDED')), amount numeric(18,2) NOT NULL CHECK(amount>=0), transaction_reference varchar(100), paid_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE order_submissions (customer_id bigint NOT NULL REFERENCES customers, request_key varchar(100) NOT NULL, request_hash varchar(64) NOT NULL, order_id bigint NOT NULL REFERENCES orders, PRIMARY KEY(customer_id,request_key));
CREATE INDEX orders_customer_idx ON orders(customer_id,id DESC);
CREATE TABLE search_queries (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, customer_id bigint REFERENCES customers, search_session varchar(80) NOT NULL, query_type varchar(20) NOT NULL, status varchar(30) NOT NULL, search_conditions jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE text_queries (id bigint PRIMARY KEY REFERENCES search_queries ON DELETE CASCADE, text varchar(100) NOT NULL);
CREATE TABLE voice_queries (id bigint PRIMARY KEY REFERENCES search_queries ON DELETE CASCADE, audio_url varchar(500) NOT NULL, transcribed_text varchar(100));
CREATE TABLE image_queries (id bigint PRIMARY KEY REFERENCES search_queries ON DELETE CASCADE, image_url varchar(500) NOT NULL, selected_region jsonb);
CREATE TABLE search_results (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, query_id bigint NOT NULL REFERENCES search_queries ON DELETE CASCADE, product_id bigint NOT NULL REFERENCES products, rank integer NOT NULL CHECK(rank>=1), score numeric, UNIQUE(query_id,rank), UNIQUE(query_id,product_id));
CREATE INDEX search_cleanup_idx ON search_queries(created_at);
CREATE INDEX product_search_idx ON products USING gin(search_text gin_trgm_ops);
CREATE FUNCTION refresh_product_search() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.search_text=lower(unaccent(NEW.name || ' ' || NEW.description || ' ' || COALESCE((SELECT name FROM categories WHERE id=NEW.category_id),''))); RETURN NEW; END $$;
CREATE TRIGGER product_search_refresh BEFORE INSERT OR UPDATE OF name,description,category_id ON products FOR EACH ROW EXECUTE FUNCTION refresh_product_search();
CREATE FUNCTION refresh_category_search() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN UPDATE products SET name=name WHERE category_id=NEW.id; RETURN NEW; END $$;
CREATE TRIGGER category_search_refresh AFTER UPDATE OF name ON categories FOR EACH ROW EXECUTE FUNCTION refresh_category_search();
CREATE TABLE spring_session (primary_id char(36) PRIMARY KEY, session_id char(36) NOT NULL UNIQUE, creation_time bigint NOT NULL, last_access_time bigint NOT NULL, max_inactive_interval integer NOT NULL, expiry_time bigint NOT NULL, principal_name varchar(100));
CREATE INDEX spring_session_expiry_idx ON spring_session(expiry_time);
CREATE INDEX spring_session_principal_idx ON spring_session(principal_name);
CREATE TABLE spring_session_attributes (session_primary_id char(36) NOT NULL REFERENCES spring_session(primary_id) ON DELETE CASCADE, attribute_name varchar(200) NOT NULL, attribute_bytes bytea NOT NULL, PRIMARY KEY(session_primary_id,attribute_name));
